cssCode:
.flashlight-wrap {
  width: 100%; height: 100%; position: relative;
  background: #050505; display: flex; align-items: center; justify-content: center;
  overflow: hidden; touch-action: none;
}
.hidden-text {
  font-size: 50px; font-weight: 900; color: #1a1a1a;
  font-family: sans-serif; letter-spacing: 2px; position: relative; z-index: 1;
}
.light-beam {
  position: absolute; top: 0; left: 0; width: 100%; height: 100%;
  pointer-events: none; z-index: 2; mix-blend-mode: color-dodge;
  background: radial-gradient(circle 0px at 50% 50%, rgba(0, 255, 204, 0), transparent 100%);
  transition: background 0.1s;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;background:#050505;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden;touch-action:none;';

const wrap = document.createElement('div');
wrap.className = 'flashlight-wrap';

const textEl = document.createElement('div');
textEl.className = 'hidden-text';
textEl.innerText = 'MOTIONZYNC';

const light = document.createElement('div');
light.className = 'light-beam';

wrap.appendChild(textEl);
wrap.appendChild(light);
c.appendChild(wrap);

c.addEventListener('pointermove', (e) => {
  const rect = c.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  light.style.background = `radial-gradient(circle 120px at ${x}px ${y}px, rgba(0, 255, 204, 0.9), transparent 100%)`;
});
c.addEventListener('pointerleave', () => {
  light.style.background = `radial-gradient(circle 0px at 50% 50%, rgba(0, 255, 204, 0), transparent 100%)`;
});
